files.content:
.root {
  --vt-surface: #fafcfd;
  --vt-surface-2: #f0f5f7;
  --vt-surface-deep: #e8f0f3;
  --vt-ink: #2c3e44;
  --vt-ink-soft: #5f7a84;
  --vt-on-deep: #2c3e44;
  --vt-accent: #5b7a8a;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #3d5561;
  --vt-accent-on-deep: #3d5561;
  --vt-line: #dce6ea;
  --font-serif: 'Noto Serif Display', Georgia, serif;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.7;
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  -webkit-font-smoothing: antialiased;
}
.root *, .root *::before, .root *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
.root :where(a) {
  color: inherit;
  text-decoration: none;
  transition: color 0.2s ease;
}
.root a:hover {
  color: var(--vt-accent-ink);
}
.root :where(img) {
  max-width: 100%;
  display: block;
}
.root :where(h1, h2, h3, h4) {
  font-family: var(--font-serif);
  font-weight: 400;
  line-height: 1.3;
  color: inherit;
}
.root :where(p) {
  margin-bottom: 1rem;
}

.container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 2rem;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}
.navInner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4rem;
}
.logo {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  color: var(--vt-ink);
}
.navLinks {
  display: flex;
  gap: 2rem;
}
.navLinks a {
  font-size: 0.9375rem;
  color: var(--vt-ink-soft);
}
.navLinks a:hover {
  color: var(--vt-ink);
}

.hero {
  padding: 7rem 0 6rem;
}
.heroGrid {
  display: grid;
  gap: 4rem;
  align-items: center;
}
.heroContent {
  max-width: 540px;
}
.tagline {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  margin-bottom: 0.5rem;
}
.heroTitle {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  letter-spacing: -0.02em;
  margin-bottom: 1rem;
}
.heroDescription {
  font-size: 1.125rem;
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}
.btnGroup {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}
.btnPrimary, .btnSecondary {
  display: inline-block;
  padding: 0.875rem 1.75rem;
  font-family: var(--font-sans);
  font-size: 0.9375rem;
  font-weight: 500;
  text-align: center;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.btnPrimary {
  background-color: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 1px solid transparent;
}
.btnPrimary:hover {
  background-color: var(--vt-accent-ink);
  color: var(--vt-on-accent);
}
.btnSecondary {
  background-color: transparent;
  color: var(--vt-ink);
  border: 1px solid var(--vt-line);
}
.btnSecondary:hover {
  background-color: var(--vt-surface-2);
  border-color: var(--vt-ink-soft);
  color: var(--vt-ink);
}

.heroVisual {
  display: flex;
  justify-content: center;
  align-items: center;
}
.albumShowcase {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}
.albumCover {
  position: relative;
  width: 280px;
  height: 280px;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 20px 60px color-mix(in srgb, var(--vt-ink) 15%, transparent), 0 8px 20px color-mix(in srgb, var(--vt-ink) 10%, transparent);
}
.albumCover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.albumReflection {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, color-mix(in srgb, var(--vt-on-accent) 20%, transparent) 0%, color-mix(in srgb, var(--vt-on-accent) 0%, transparent) 50%);
  pointer-events: none;
}
.visualizer {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  gap: 4px;
  height: 40px;
  padding: 1rem 2rem;
  background-color: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
}
.bar {
  width: 4px;
  background-color: var(--vt-accent);
  border-radius: 2px;
  transform-origin: bottom;
  animation: visualizer 0.8s ease-in-out infinite alternate;
}
.bar:nth-child(1) { height: 12px; animation-delay: 0s; }
.bar:nth-child(2) { height: 20px; animation-delay: 0.1s; }
.bar:nth-child(3) { height: 16px; animation-delay: 0.15s; }
.bar:nth-child(4) { height: 28px; animation-delay: 0.2s; }
.bar:nth-child(5) { height: 24px; animation-delay: 0.05s; }
.bar:nth-child(6) { height: 32px; animation-delay: 0.25s; }
.bar:nth-child(7) { height: 28px; animation-delay: 0.1s; }
.bar:nth-child(8) { height: 20px; animation-delay: 0.3s; }
.bar:nth-child(9) { height: 24px; animation-delay: 0.15s; }
.bar:nth-child(10) { height: 16px; animation-delay: 0.2s; }
.bar:nth-child(11) { height: 20px; animation-delay: 0.05s; }
.bar:nth-child(12) { height: 12px; animation-delay: 0.25s; }
@keyframes visualizer {
  0% { transform: scaleY(0.3); }
  100% { transform: scaleY(1); }
}
.albumInfo {
  text-align: center;
}
.albumBadge {
  display: inline-block;
  padding: 4px 12px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  background-color: var(--vt-surface-deep);
  border-radius: 20px;
  margin-bottom: 0.5rem;
}
.albumInfo h3 {
  font-size: 1.25rem;
  margin-bottom: 4px;
}
.albumInfo p {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
  margin-bottom: 0;
}

.about {
  background-color: var(--vt-surface-2);
  padding: 6rem 0;
}
.aboutGrid {
  display: grid;
  gap: 4rem;
  align-items: center;
}
.aboutImageWrap {
  aspect-ratio: 4 / 5;
  background-color: var(--vt-line);
  border-radius: 8px;
  overflow: hidden;
  max-width: 280px;
}
.aboutImageWrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 1.0625rem;
}
.sectionLabel {
  display: block;
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--vt-accent-ink);
  margin-bottom: 0.5rem;
}
.aboutText h2 {
  margin-bottom: 2rem;
}

.services {
  padding: 6rem 0;
}
.services h2 {
  margin-bottom: 2rem;
}
.servicesGrid {
  display: grid;
  gap: 2rem;
}
.serviceCard {
  position: relative;
  padding: 2rem;
  background-color: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  transition: border-color 0.2s ease;
}
.serviceCard:hover {
  border-color: var(--vt-accent);
}
.serviceIcon {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--vt-surface-deep);
  border-radius: 8px;
  margin-bottom: 1rem;
  color: var(--vt-accent);
}
.serviceIcon svg {
  width: 32px;
  height: 32px;
}
.serviceNum {
  position: absolute;
  top: 1.25rem;
  right: 1.25rem;
  font-size: 0.75rem;
  letter-spacing: 0.08em;
  color: var(--vt-ink-soft);
}
.serviceCard h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}
.serviceCard p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}
.serviceMeta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  font-size: 0.8125rem;
  color: var(--vt-accent-ink);
}
.serviceMeta span {
  padding: 0.25rem 0.5rem;
  background-color: var(--vt-surface-deep);
  border-radius: 4px;
}

.work {
  background-color: var(--vt-surface-2);
  padding: 6rem 0;
}
.work h2 {
  margin-bottom: 2rem;
}
.workGrid {
  display: grid;
  gap: 2rem;
}
.workCard {
  background-color: var(--vt-surface);
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--vt-line);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.workCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 32px color-mix(in srgb, var(--vt-ink) 8%, transparent);
}
.workImage {
  aspect-ratio: 16 / 10;
  background-color: var(--vt-line);
  overflow: hidden;
}
.workImage img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.workInfo {
  padding: 1rem 2rem 2rem;
}
.workCategory {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.5rem;
}
.workInfo h3 {
  font-size: 1.25rem;
  margin-bottom: 0.5rem;
}
.workInfo p {
  color: var(--vt-ink-soft);
  font-size: 0.9375rem;
  margin-bottom: 0;
}

.contact {
  background-color: var(--vt-surface-deep);
  padding: 6rem 0;
}
.contactGrid {
  display: grid;
  gap: 2rem;
  align-items: center;
}
.contactInfo h2 {
  margin-bottom: 0.5rem;
}
.contactInfo p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}
.socialLinks {
  display: flex;
  gap: 0.5rem;
}
.socialLinks a {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--vt-surface);
  border-radius: 50%;
  color: var(--vt-ink);
  transition: background-color 0.2s ease, color 0.2s ease;
}
.socialLinks a:hover {
  background-color: var(--vt-accent);
  color: var(--vt-on-accent);
}
.contactAside {
  background-color: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  padding: 1.5rem;
}

.footer {
  padding: 2rem 0;
  background-color: var(--vt-surface);
  border-top: 1px solid var(--vt-line);
}
.footerInner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}
.footerCopyright {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
  margin: 0;
}
.footerCredit {
  font-size: 0.875rem;
  color: var(--vt-ink-soft);
}
.footerCredit:hover {
  color: var(--vt-accent);
}

@media (min-width: 640px) {
  .servicesGrid { grid-template-columns: repeat(2, 1fr); }
  .workGrid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 768px) {
  .aboutGrid { grid-template-columns: 1fr; }
  .aboutGrid:has(.aboutImageWrap) { grid-template-columns: 1fr 1.5fr; gap: 4rem; }
  .aboutImageWrap { max-width: none; }
  .servicesGrid { grid-template-columns: repeat(3, 1fr); }
  .workGrid { grid-template-columns: repeat(3, 1fr); }
  .contactGrid { grid-template-columns: 1fr 1.5fr; gap: 4rem; }
}
@media (min-width: 900px) {
  .heroGrid { grid-template-columns: 1fr; }
  .heroGrid:has(.heroVisual) { grid-template-columns: 1fr 1fr; gap: 6rem; }
  .albumCover { width: 340px; height: 340px; }
}
@media (max-width: 767px) {
  .navInner { flex-wrap: wrap; height: auto; padding: 0.75rem 0; gap: 0.5rem; }
  .navLinks { flex: 1 1 100%; justify-content: center; gap: 1rem; }
}
@media (prefers-reduced-motion: reduce) {
  .bar { animation: none; }
  .workCard { transition: none; }
  .btnPrimary, .btnSecondary { transition: none; }
}
